46	/**
47	 * Global Exception handler for REST controllers.
48	 * <p>
49	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
50	 *
51	 * @author Vitaliy Fedoriv
52	 * @author Alexander Dudkin
53	 */
54	@ControllerAdvice
55	public class ExceptionControllerAdvice {
56	
57	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
58	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
59	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
60	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
61	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the same identity already exists";
62	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
63	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners has already been registered today";
64	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The registration date may not be later than the current date";
65	    private static final String ERROR_DISPOSABLE_EMAIL_DOMAIN = "The owner's email uses a disposable email domain, which is not allowed";
66	
67	    /**
68	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
69	     * class.
70	     *
71	     * @param e     Object referring to the thrown exception.
72	     * @param status HTTP response status.
73	     * @param url URL request.
74	     */
75	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
76	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
77	        problemDetail.setType(URI.create(url.toString()));
78	        problemDetail.setTitle(e.getClass().getSimpleName());
79	        problemDetail.setDetail(detail);
80	        problemDetail.setProperty("timestamp", Instant.now());
81	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
82	        return problemDetail;
83	    }
84	
85	    /**
86	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
87	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
88	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
89	     * would catch it and report an authorization failure as a 500.
90	     *
91	     * @param e The {@link AccessDeniedException} to propagate
92	     * @throws AccessDeniedException always
93	     */
94	    @ExceptionHandler(AccessDeniedException.class)
95	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
96	        throw e;
97	    }
98	
99	    /**
100	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
101	     *
102	     * @param e The {@link Exception} to be handled
103	     * @param request {@link HttpServletRequest} object referring to the current request.
104	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
105	     */
106	    @ExceptionHandler(Exception.class)
107	    @ResponseBody
108	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
109	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
110	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
111	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
112	        return ResponseEntity.status(status).body(detail);
113	    }
114	
115	    /**
116	     * Handles {@link DuplicateIdentityException}, raised when an owner is saved whose derived
117	     * {@code identityKey} (the single duplicate-detection key: the SHA-256 hex over normalized
118	     * telephone, lower-cased email and last-name Soundex) already belongs to another owner, by
119	     * returning a 409 Conflict status.
120	     *
121	     * @param e The {@link DuplicateIdentityException} to be handled
122	     * @param request {@link HttpServletRequest} object referring to the current request.
123	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
124	     */
125	    @ExceptionHandler(DuplicateIdentityException.class)
126	    @ResponseBody
127	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
128	        logger.warn("Duplicate identity at {} {}: {}",
129	            request.getMethod(),
130	            request.getRequestURI(),
131	            e.getMessage());
132	        HttpStatus status = HttpStatus.CONFLICT;
133	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
134	        return ResponseEntity.status(status).body(detail);
135	    }
136	
137	    /**
138	     * Handles {@link CityAtCapacityException}, raised when a new owner is created whose city already
139	     * contains the maximum number of owners, by returning a 409 Conflict status.
140	     *
141	     * @param e The {@link CityAtCapacityException} to be handled
142	     * @param request {@link HttpServletRequest} object referring to the current request.
143	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
144	     */
145	    @ExceptionHandler(CityAtCapacityException.class)
146	    @ResponseBody
147	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
148	        logger.warn("City at capacity at {} {}: {}",
149	            request.getMethod(),
150	            request.getRequestURI(),
151	            e.getMessage());
152	        HttpStatus status = HttpStatus.CONFLICT;
153	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
154	        return ResponseEntity.status(status).body(detail);
155	    }
156	
157	    /**
158	     * Handles {@link DailyRegistrationLimitException}, raised when a new owner is created on a day
159	     * that already has the maximum number of owners registered (counted by {@code registrationDate}),
160	     * by returning a 429 Too Many Requests status.
161	     *
162	     * @param e The {@link DailyRegistrationLimitException} to be handled
163	     * @param request {@link HttpServletRequest} object referring to the current request.
164	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
165	     */
166	    @ExceptionHandler(DailyRegistrationLimitException.class)
167	    @ResponseBody
168	    public ResponseEntity<ProblemDetail> handleDailyRegistrationLimitException(DailyRegistrationLimitException e, HttpServletRequest request) {
169	        logger.warn("Daily registration limit reached at {} {}: {}",
170	            request.getMethod(),
171	            request.getRequestURI(),
172	            e.getMessage());
173	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
174	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
175	        return ResponseEntity.status(status).body(detail);
176	    }
177	
178	    /**
179	     * Handles {@link FutureRegistrationDateException}, raised when an owner is saved with a supplied
180	     * {@code registrationDate} later than the current server date, by returning a 400 Bad Request status.
181	     *
182	     * @param e The {@link FutureRegistrationDateException} to be handled
183	     * @param request {@link HttpServletRequest} object referring to the current request.
184	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
185	     */
186	    @ExceptionHandler(FutureRegistrationDateException.class)
187	    @ResponseBody
188	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
189	        logger.warn("Future registration date at {} {}: {}",
190	            request.getMethod(),
191	            request.getRequestURI(),
192	            e.getMessage());
193	        HttpStatus status = HttpStatus.BAD_REQUEST;
194	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_FUTURE_REGISTRATION_DATE);
195	        return ResponseEntity.status(status).body(detail);
196	    }
197	
198	    /**
199	     * Handles {@link DisposableEmailDomainException}, raised when an owner is saved with an email
200	     * whose domain is on the disposable-domain blocklist, by returning a 400 Bad Request status.
201	     *
202	     * @param e The {@link DisposableEmailDomainException} to be handled
203	     * @param request {@link HttpServletRequest} object referring to the current request.
204	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
205	     */
206	    @ExceptionHandler(DisposableEmailDomainException.class)
207	    @ResponseBody
208	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
209	        logger.warn("Disposable email domain at {} {}: {}",
210	            request.getMethod(),
211	            request.getRequestURI(),
212	            e.getMessage());
213	        HttpStatus status = HttpStatus.BAD_REQUEST;
214	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DISPOSABLE_EMAIL_DOMAIN);
215	        return ResponseEntity.status(status).body(detail);
216	    }
217	
218	    /**
219	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
220	     * method returns a 404 Not Found status if an entity does not exist.
221	     *
222	     * @param e The {@link DataIntegrityViolationException} to be handled
223	     * @param request {@link HttpServletRequest} object referring to the current request.
224	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
225	     */
226	    @ExceptionHandler(DataIntegrityViolationException.class)
227	    @ResponseBody
228	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
229	        logger.warn("Data integrity violation at {} {}: {}",
230	            request.getMethod(),
231	            request.getRequestURI(),
232	            e.getMessage());
233	        logger.debug("Data integrity violation stacktrace", e);
234	        HttpStatus status = HttpStatus.NOT_FOUND;
235	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
236	        return ResponseEntity.status(status).body(detail);
237	    }
238	
239	    /**
240	     * Handles exception thrown by Bean Validation on controller methods parameters
241	     *
242	     * @param e The {@link MethodArgumentNotValidException} to be handled
243	     * @param request {@link HttpServletRequest} object referring to the current request.
244	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
245	     */
246	    @ExceptionHandler(MethodArgumentNotValidException.class)
247	    @ResponseBody
248	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
249	        HttpStatus status = HttpStatus.BAD_REQUEST;
250	        BindingErrorsResponse errors = new BindingErrorsResponse();
251	        BindingResult bindingResult = e.getBindingResult();
252	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
253	        if (bindingResult.hasErrors()) {
254	            errors.addAllErrors(bindingResult);
255	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
256	                .map(fieldError -> {
257	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
258	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
259	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
260	                        fieldError.getField(),
261	                        defaultMessage,
262	                        rejectedValue);
263	                    return new ValidationMessageDto(message)
264	                        .putAdditionalProperty("field", fieldError.getField())
265	                        .putAdditionalProperty("rejectedValue", rejectedValue)
266	                        .putAdditionalProperty("defaultMessage", defaultMessage);
267	                })
268	                .toList();
269	            logger.debug("Validation error at {} {}: {}",
270	                request.getMethod(),
271	                request.getRequestURI(),
272	                bindingResult.getFieldErrors());
273	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
274	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
275	                .map(FieldError::getField)
276	                .distinct()
277	                .toList();
278	            detail.setProperty("errors", invalidFields);
279	            return ResponseEntity.status(status).body(detail);
280	        }
281	        return ResponseEntity.status(status).body(detail);
282	    }
283	
284	}
